void NodeGraphComponent::setModulationDepth(const NodeId nodeId,
                                            const juce::String& binding,
                                            const double depth)
{
    auto* stored = findNode(nodeId);
    if (stored == nullptr)
        return;
    const auto rangeId = modulationRangeNodeFor(*stored, binding);
    auto* rangeNode = rangeId != 0 ? findNode(rangeId) : nullptr;
    if (rangeNode == nullptr)
        return;
    const auto centre = (rangeNode->parameters.mapOutputMinimum
                         + rangeNode->parameters.mapOutputMaximum) * 0.5f;
    rangeNode->parameters.mapOutputMinimum = centre - static_cast<float>(depth);
    rangeNode->parameters.mapOutputMaximum = centre + static_cast<float>(depth);
    for (auto& parameter : rangeNode->interfaceState.parameters)
        if (bindingMatchesType(rangeNode->typeKey, parameter.key))
            parameter.value = nativeParameterValue(rangeNode->parameters,
                                                   parameter.key);
    for (auto& embedded : embeddedSliders_)
        if (embedded.nodeId == nodeId && embedded.binding == binding)
            if (auto* knob = dynamic_cast<KnobSlider*>(embedded.slider.get()))
                knob->setModulationRange(
                    juce::Range<double>(centre - std::abs(depth),
                                        centre + std::abs(depth)),
                    depth < 0.0);
    repaint(nodeBounds(*rangeNode).toNearestInt());
    queueParameterNotification();
}

void NodeGraphComponent::removeModulation(const NodeId nodeId,
                                          const juce::String& binding)
{
    if (editingLocked_)
        return;
    auto* stored = findNode(nodeId);
    if (stored == nullptr)
        return;
    const auto rangeId = modulationRangeNodeFor(*stored, binding);
    const auto* rangeNode = rangeId != 0 ? readNode(rangeId) : nullptr;
    if (rangeNode == nullptr)
        return;
    // The centre the knob was showing becomes its value again: a turn given
    // to a modulated knob is not lost with the cable.
    const auto centre = static_cast<double>(
        (rangeNode->parameters.mapOutputMinimum
         + rangeNode->parameters.mapOutputMaximum) * 0.5f);
    if (findModule(stored->typeKey) != nullptr) {
        (void) updateGraphInstanceParameter(*stored, binding, centre);
    } else {
        (void) updateNodeParameter(*stored, binding, centre);
        for (auto& parameter : stored->interfaceState.parameters)
            if (parameter.key == binding)
                parameter.value = centre;
    }
    if (auto* presentation = editablePresentationForNode(*stored)) {
        const auto parameter = std::ranges::find_if(
            presentation->parameters, [&binding](const auto& candidate) {
                return candidate.key == binding;
            });
        if (parameter != presentation->parameters.end())
            parameter->value = centre;
    }
    std::erase_if(connections_, [rangeId](const auto& connection) {
        return connection.source == rangeId
               || connection.destination == rangeId;
    });
    std::erase_if(nodes_, [rangeId](const auto& node) {
        return node.id == rangeId;
    });
    selectedNodes_.erase(rangeId);
    synchroniseGraphInterface();
    rebuildEmbeddedSliders();
    refreshSelectionDetails();
    setStatus(tr("nodes.status.unmodulated"));
    resized();
    repaint();
    notifyLayoutChanged("unmodulate");
}

bool NodeGraphComponent::removeModulationForTest(
    const juce::String& targetTypeKey, const juce::String& parameterSuffix)
{
    const auto target = nodeIdForType(targetTypeKey);
    const auto binding = nodeParameterBinding(target, parameterSuffix);
    const auto* stored = readNode(target);
    if (stored == nullptr || modulationRangeNodeFor(*stored, binding) == 0)
        return false;
    removeModulation(target, binding);
    return true;
}

