juce::StringArray NodeGraphComponent::deviceNames(const int limit) const
{
    juce::StringArray names;
    for (const auto& node : nodes_) {
        const auto& type = node.typeKey;
        if (type == "audio-clips" || type == "master" || type == "midi-input"
            || type == "transport" || type.startsWith("graph-"))
            continue;
        const auto title = node.title.isEmpty() ? type : node.title;
        if (!names.contains(title, true))
            names.add(title);
        if (limit > 0 && names.size() >= limit)
            break;
    }
    return names;
}

juce::Rectangle<int> NodeGraphComponent::nodeBoundsForTest(
    const juce::String& nodeTypeKey) const
{
    const auto* node = readNode(nodeIdForType(nodeTypeKey));
    return node != nullptr ? nodeBounds(*node).toNearestInt()
                           : juce::Rectangle<int> {};
}

void NodeGraphComponent::setControlValues(
    const std::vector<std::pair<std::uint64_t, float>>& values)
{
    controlValues_.clear();
    for (const auto& [nodeId, value] : values)
        if (std::isfinite(value))
            controlValues_.emplace(nodeId, value);
    // A modulated knob's range node reports the parameter's value at this
    // instant, in the knob's units: that is the dot on its ring.
    for (auto& embedded : embeddedSliders_) {
        auto* knob = dynamic_cast<KnobSlider*>(embedded.slider.get());
        if (knob == nullptr)
            continue;
        if (embedded.modulationRangeNodeId == 0) {
            knob->setModulationPosition(std::nullopt);
            continue;
        }
        const auto found = controlValues_.find(embedded.modulationRangeNodeId);
        knob->setModulationPosition(
            found != controlValues_.end()
                ? std::optional<double>(static_cast<double>(found->second))
                : std::nullopt);
    }
    // Only the cards whose value this is. Thirty times a second, the whole
    // canvas for a handful of numbers was the other half of the playback
    // repaint.
    const auto canvas = canvasBounds();
    for (const auto& [nodeId, value] : controlValues_)
        if (const auto* node = readNode(nodeId)) {
            const auto bounds = nodeBounds(*node).toNearestInt().expanded(2);
            if (bounds.intersects(canvas))
                repaint(bounds.getIntersection(canvas));
        }
}

void NodeGraphComponent::clearAnalysis() noexcept
{
    if (moduleInterfaceEditor_ != nullptr)
        moduleInterfaceEditor_->clearAnalysis();
    analysisActive_ = false;
    analysisWaveformCount_ = 0;
    analysisWaveform_.fill(0.0f);
    analysisSpectrum_.fill(0.0f);
    analysisPeak_.fill(0.0f);
    analysisRms_.fill(0.0f);
    analysisChannelCount_ = 2;
    eqSpectrum_.fill(0.0f);
    eqSpectrumHeld_ = false;
    lastAnalysisFrameHeld_ = false;
    for (auto& embedded : embeddedEqCurves_)
        if (embedded.curve != nullptr)
            embedded.curve->setSpectrum(nullptr, 0);
    repaint();
}

