void NodeGraphComponent::commitGraphMetadata()
{
    if (editingLocked_)
        return;
    const auto nextName = graphNameEditor_.getText().trim().substring(0, 128);
    const auto nextCategory = graphCategoryEditor_.getText().trim()
                                  .substring(0, 192);
    const auto nextAuthor = graphAuthorEditor_.getText().trim()
                                .substring(0, 128);
    const auto nextDescription = graphDescriptionEditor_.getText().trim()
                                     .substring(0, 2'048);
    auto nextTags = juce::StringArray::fromTokens(
        graphTagsEditor_.getText(), ",;", "\"");
    juce::StringArray cleanTags;
    for (auto tag : nextTags) {
        tag = tag.trim().substring(0, 48);
        if (tag.isNotEmpty())
            cleanTags.addIfNotAlreadyThere(tag, true);
        if (cleanTags.size() >= 12)
            break;
    }
    if (graphName_ == nextName && graphCategory_ == nextCategory
        && graphAuthor_ == nextAuthor
        && graphDescription_ == nextDescription
        && graphTags_ == cleanTags)
        return;
    graphName_ = nextName;
    graphCategory_ = nextCategory;
    graphAuthor_ = nextAuthor;
    graphDescription_ = nextDescription;
    graphTags_ = cleanTags;
    graphTagsEditor_.setText(graphTags_.joinIntoString(", "), false);
    const auto breadcrumbName = graphName_.isNotEmpty() ? graphName_ : contextName_;
    breadcrumbLabel_.setText(
        tr("nodes.toolbar.breadcrumb", "name", breadcrumbName),
        juce::dontSendNotification);
    breadcrumbLabel_.setTooltip(graphTooltip());
    refreshGraphMetadataSummary();
    refreshGraphAssetValidation();
    refreshGraphManager();
    notifyLayoutChanged();
    repaint();
}

void NodeGraphComponent::bumpGraphVersion(const int component)
{
    if (editingLocked_)
        return;
    auto next = graphReference_.version;
    constexpr auto maximum = std::numeric_limits<std::uint16_t>::max();
    if (component == 0) {
        if (next.major == maximum) {
            setStatus(tr("nodes.status.versionLimit"), true);
            return;
        }
        ++next.major;
        next.minor = 0;
        next.patch = 0;
    } else if (component == 1) {
        if (next.minor == maximum) {
            setStatus(tr("nodes.status.versionLimit"), true);
            return;
        }
        ++next.minor;
        next.patch = 0;
    } else {
        if (next.patch == maximum) {
            setStatus(tr("nodes.status.versionLimit"), true);
            return;
        }
        ++next.patch;
    }
    graphReference_.version = next;
    refreshGraphMetadataSummary();
    refreshGraphAssetValidation();
    refreshGraphManager();
    setStatus(tr("nodes.status.versionBumped", "version",
                 juce::String(next.toString())));
    notifyLayoutChanged();
    repaint();
}

void NodeGraphComponent::forkGraphDefinition()
{
    if (editingLocked_)
        return;

    const auto previousName = graphName_.isNotEmpty()
        ? graphName_
        : contextName_.isNotEmpty() ? contextName_
                                    : tr("nodes.graphNamePlaceholder");
    auto slug = juce::File::createLegalFileName(previousName)
                    .toLowerCase()
                    .replaceCharacter(' ', '-');
    slug = slug.retainCharacters(
        "abcdefghijklmnopqrstuvwxyz0123456789-_");
    while (slug.contains("--"))
        slug = slug.replace("--", "-");
    slug = slug.trimCharactersAtStart("-_")
               .trimCharactersAtEnd("-_");
    if (slug.isEmpty())
        slug = "graph";

    const auto uniqueSuffix = juce::Uuid().toString()
                                  .removeCharacters("{}-")
                                  .toLowerCase().substring(0, 12);
    graphReference_.id = ("user." + slug.substring(0, 96)
                          + "." + uniqueSuffix).toStdString();
    currentGraphPresetFile_ = {};
    graphReference_.version = { 1, 0, 0 };
    graphScope_ = cydaw::graph::GraphScope::user;
    graphName_ = tr("nodes.forkedGraphName", "name", previousName)
                     .substring(0, 128);
    graphNameEditor_.setText(graphName_, false);
    graphScopeSelector_.setSelectedId(
        static_cast<int>(graphScope_) + 1, juce::dontSendNotification);
    activeFactoryPresetKey_.clear();

    // A fork is a new public contract. Preserve the author/company defaults,
    // but derive the product name and plug-in code from the new identity.
    pluginExportIdentity_.productName = graphName_.toStdString();
    pluginExportIdentity_.pluginCode.clear();
    pluginExportIdentity_.version = { 1, 0, 0 };

    breadcrumbLabel_.setText(
        tr("nodes.toolbar.breadcrumb", "name", graphName_),
        juce::dontSendNotification);
    breadcrumbLabel_.setTooltip(graphTooltip());
    refreshGraphMetadataSummary();
    refreshGraphAssetValidation();
    refreshGraphManager();
    setStatus(tr("nodes.status.graphForked", "name", graphName_));
    notifyLayoutChanged();
    repaint();
}

void NodeGraphComponent::checkVst3Export()
{
    commitGraphMetadata();
    openVst3ExportPanel();
}

cydaw::graph::PluginIdentity
NodeGraphComponent::defaultVst3ExportIdentity() const
{
    std::uint32_t hash = 2'166'136'261u;
    for (const auto value : graphReference_.id) {
        hash ^= static_cast<std::uint8_t>(value);
        hash *= 16'777'619u;
    }
    const auto pluginCode = "G"
        + juce::String::toHexString(static_cast<int>(hash & 0xfffu))
              .paddedLeft('0', 3).toUpperCase();
    const auto productName = graphName_.isNotEmpty()
                                 ? graphName_
                                 : (contextName_.isNotEmpty()
                                        ? contextName_
                                        : juce::String("CyDAW Graph"));
    return {
        productName.toStdString(), "CyDAW User", "CyDw",
        pluginCode.toStdString(), graphReference_.version
    };
}

cydaw::graph::PluginExportResult NodeGraphComponent::planVst3Export(
    const cydaw::graph::PluginIdentity& identity) const
{
    cydaw::graph::GraphLibrary library;
    const auto installed = library.installBatch(graphDefinitions());
    if (!installed.ok()) {
        cydaw::graph::PluginExportResult result;
        for (const auto& issue : installed.issues)
            if (issue.severity == cydaw::graph::ValidationSeverity::error)
                result.issues.push_back({
                    cydaw::graph::PluginExportIssueCode::invalidGraph,
                    issue.message, issue.portId, {}
                });
        if (result.issues.empty())
            result.issues.push_back({
                cydaw::graph::PluginExportIssueCode::invalidGraph,
                "The Graph library could not be installed for VST3 export",
                {}, {}
            });
        return result;
    }
    return cydaw::graph::planVst3Export(
        library, graphReference_, identity);
}

void NodeGraphComponent::openVst3ExportPanel()
{
    if (vst3ExportWindow_ != nullptr) {
        if (vst3ExportPanel_ != nullptr) {
            vst3ExportPanel_->setProfile(pluginExportIdentity());
            vst3ExportPanel_->refreshTranslations();
            vst3ExportPanel_->validateNow();
        }
        vst3ExportWindow_->setVisible(true);
        vst3ExportWindow_->toFront(true);
        return;
    }

    auto panel = std::make_unique<GraphPluginExportComponent>();
    vst3ExportPanel_ = panel.get();
    panel->setProfile(pluginExportIdentity());
    juce::Component::SafePointer<NodeGraphComponent> safeThis(this);
    panel->setValidationHandler(
        [safeThis](const cydaw::graph::PluginIdentity& identity) {
            return safeThis != nullptr
                       ? safeThis->planVst3Export(identity)
                       : cydaw::graph::PluginExportResult {};
        });
    panel->setProfileChangedHandler(
        [safeThis](cydaw::graph::PluginIdentity identity) {
            if (safeThis != nullptr)
                safeThis->setPluginExportIdentity(std::move(identity));
        });
    panel->setSaveManifestHandler(
        [safeThis](const cydaw::graph::PluginIdentity& identity,
                   const cydaw::graph::PluginExportPlan& plan) {
            if (safeThis != nullptr)
                safeThis->saveVst3ExportManifest(identity, plan);
        });
    panel->setGenerateProjectHandler(
        [safeThis](const cydaw::graph::PluginIdentity& identity,
                   const cydaw::graph::PluginExportPlan& plan) {
            if (safeThis != nullptr)
                safeThis->chooseVst3ProjectDirectory(identity, plan);
        });
    panel->validateNow();

    auto window = std::make_unique<ModuleEditorDocumentWindow>(
        tr("graph.export.windowTitle"));
    window->setContentOwned(panel.release(), true);
    window->setResizeLimits(760, 480, 1'920, 1'200);
    window->centreWithSize(920, 590);
    window->setVisible(true);
    window->toFront(true);
    vst3ExportWindow_ = std::move(window);

    const auto result = planVst3Export();
    if (!result) {
        setStatus(result.issues.empty()
                      ? tr("nodes.status.vst3Invalid")
                      : juce::String(result.issues.front().message),
                  true);
        return;
    }
    setStatus(tr("nodes.status.vst3Ready", "name",
                 juce::String(result.plan->identity.productName)));
}

void NodeGraphComponent::saveVst3ExportManifest(
    const cydaw::graph::PluginIdentity& identity,
    const cydaw::graph::PluginExportPlan& plan)
{
    setPluginExportIdentity(identity);
    auto directory = juce::File::getSpecialLocation(
                         juce::File::userDocumentsDirectory)
                         .getChildFile("CyDAW")
                         .getChildFile("Plugin Exports");
    (void) directory.createDirectory();
    auto name = juce::File::createLegalFileName(
        juce::String(identity.productName).trim());
    if (name.isEmpty())
        name = "CyDAW Graph";
    vst3ManifestChooser_ = std::make_unique<juce::FileChooser>(
        tr("graph.export.chooseManifest"),
        directory.getChildFile(name + ".cydawvst3.json"),
        "*.cydawvst3.json;*.json");
    const auto manifest = serialisePluginExportPlan(plan, serialise());
    juce::Component::SafePointer<NodeGraphComponent> safeThis(this);
    vst3ManifestChooser_->launchAsync(
        juce::FileBrowserComponent::saveMode
            | juce::FileBrowserComponent::canSelectFiles
            | juce::FileBrowserComponent::warnAboutOverwriting,
        [safeThis, manifest](const juce::FileChooser& chooser) {
            if (safeThis == nullptr)
                return;
            auto destination = chooser.getResult();
            if (destination == juce::File {})
                return;
            if (!destination.getFileName().endsWithIgnoreCase(
                    ".cydawvst3.json"))
                destination = destination.withFileExtension(
                    ".cydawvst3.json");
            const auto json = juce::JSON::toString(manifest, true);
            if (!destination.replaceWithText(json)) {
                safeThis->setStatus(
                    tr("graph.export.saveFailed"), true);
                return;
            }
            safeThis->setStatus(
                tr("graph.export.manifestSaved", "name",
                   destination.getFileName()));
        });
}

void NodeGraphComponent::chooseVst3ProjectDirectory(
    const cydaw::graph::PluginIdentity& identity,
    const cydaw::graph::PluginExportPlan& plan)
{
    setPluginExportIdentity(identity);
    auto directory = juce::File::getSpecialLocation(
                         juce::File::userDocumentsDirectory)
                         .getChildFile("CyDAW")
                         .getChildFile("Plugin Exports");
    (void) directory.createDirectory();
    auto name = juce::File::createLegalFileName(
        juce::String(identity.productName).trim());
    if (name.isEmpty())
        name = "CyDAW Graph";
    auto suggested = directory.getChildFile(name + " VST3 Project");
    (void) suggested.createDirectory();
    vst3ProjectChooser_ = std::make_unique<juce::FileChooser>(
        tr("graph.export.chooseProject"), suggested);
    const auto manifest = serialisePluginExportPlan(plan, serialise());
    const auto runtimeState = createVst3RuntimeState();
    juce::Component::SafePointer<NodeGraphComponent> safeThis(this);
    vst3ProjectChooser_->launchAsync(
        juce::FileBrowserComponent::openMode
            | juce::FileBrowserComponent::canSelectDirectories,
        [safeThis, plan, manifest, runtimeState](
            const juce::FileChooser& chooser) {
            if (safeThis == nullptr)
                return;
            const auto destination = chooser.getResult();
            if (destination == juce::File {})
                return;
            const auto result = generateGraphVst3Project(
                destination, plan, manifest, runtimeState);
            if (result.failed()) {
                safeThis->setStatus(
                    tr("graph.export.projectFailed", "error",
                       result.getErrorMessage()), true);
                return;
            }
            safeThis->setStatus(
                tr("graph.export.projectGenerated", "name",
                   destination.getFileName()));
        });
}

void NodeGraphComponent::setSelectedAudioChannels(const int channels)
{
    if (editingLocked_ || selectedNodes_.size() != 1)
        return;
    auto* node = findNode(*selectedNodes_.begin());
    if (node == nullptr)
        return;
    const auto selectedIsBoundary = isGraphAudioBoundaryKey(node->typeKey);
    if (!selectedIsBoundary
        && !primitiveSupportsVariableAudioChannels(node->typeKey))
        return;
    const auto safe = static_cast<std::uint8_t>(juce::jlimit(1, 8, channels));

    // Exact audio formats propagate through a connected polymorphic chain.
    // A fixed reusable Graph instance forms a hard boundary: changing through
    // it is rejected unless it already exposes the requested exact format.
    std::vector<NodeId> affected { node->id };
    for (auto workIndex = std::size_t {};
         workIndex < affected.size(); ++workIndex) {
        const auto currentId = affected[workIndex];
        for (const auto& link : connections_) {
            if (link.kind != PortKind::audio
                || (link.source != currentId
                    && link.destination != currentId))
                continue;
            const auto otherId = link.source == currentId
                                     ? link.destination : link.source;
            if (std::ranges::find(affected, otherId) != affected.end())
                continue;
            const auto* other = findNode(otherId);
            if (other == nullptr)
                continue;
            const auto retypable = isGraphAudioBoundaryKey(other->typeKey)
                                   || primitiveSupportsVariableAudioChannels(
                                       other->typeKey);
            const auto otherPortId = link.source == otherId
                                         ? link.sourcePort
                                         : link.destinationPort;
            const auto* otherPort = findPort(*other, otherPortId);
            const auto otherChannels = otherPort != nullptr
                ? otherPort->channels
                : link.source == otherId ? audioOutputChannels(*other)
                                         : audioInputChannels(*other);
            if (!retypable) {
                if (otherChannels != 0 && otherChannels != safe) {
                    setStatus(tr("nodes.status.channelMismatch"), true);
                    return;
                }
                continue;
            }
            affected.push_back(otherId);
        }
    }

    const auto updateInterfacePorts = [safe](ModuleInterfaceState& state) {
        const auto update = [safe](auto& controls) {
            for (auto& control : controls)
                if ((control.kind == ModuleControlKind::inputPort
                     || control.kind == ModuleControlKind::outputPort)
                    && control.portKind == 0)
                    control.portChannels = safe;
        };
        update(state.controls);
        update(state.deviceControls);
    };
    for (const auto affectedId : affected) {
        auto* current = findNode(affectedId);
        if (current == nullptr)
            continue;
        bool inputBoundary {};
        if (isGraphAudioBoundaryKey(current->typeKey, &inputBoundary)) {
            const auto nextKey = graphAudioBoundaryKey(inputBoundary, safe);
            const auto* nextType = findType(nextKey);
            if (nextType == nullptr)
                continue;
            current->typeKey = nextKey;
            current->title = nextType->title;
            current->colour = nextType->colour;
            current->hasInput = nextType->hasInput;
            current->inputKind = nextType->inputKind;
            current->hasOutput = nextType->hasOutput;
            current->outputKind = nextType->outputKind;
            current->inputChannels = nextType->inputChannels;
            current->outputChannels = nextType->outputChannels;
            current->ports = nextType->ports;
        } else {
            if (current->inputKind == PortKind::audio)
                current->inputChannels = safe;
            if (current->outputKind == PortKind::audio)
                current->outputChannels = safe;
            for (auto& port : current->ports)
                if (port.type == cydaw::graph::PortType::audio)
                    port.channels = safe;
        }
        updateInterfacePorts(current->interfaceState);
    }
    for (auto& link : connections_)
        if (link.kind == PortKind::audio
            && (std::ranges::find(affected, link.source) != affected.end()
                || std::ranges::find(affected, link.destination)
                       != affected.end()))
            link.audioChannels = safe;
    synchroniseGraphInterface();
    refreshGraphAssetValidation();
    refreshSelectionDetails();
    notifyLayoutChanged();
    repaint();
}

void NodeGraphComponent::setSelectedModuleLocked(const bool locked)
{
    if (editingLocked_ || selectedNodes_.size() != 1)
        return;
    const auto* node = findNode(*selectedNodes_.begin());
    auto* module = node != nullptr ? findModule(node->typeKey) : nullptr;
    if (module == nullptr || module->locked == locked)
        return;
    module->locked = locked;
    if (moduleGraphEditor_ != nullptr)
        closeModuleGraphEditor();
    notifyLayoutChanged();
    refreshSelectionDetails();
    repaint();
}

void NodeGraphComponent::setSelectedNodesCollapsed(const bool collapsed)
{
    if (editingLocked_ || selectedNodes_.empty())
        return;
    struct PreviousPlacement {
        NodeId id {};
        juce::Point<float> screenTopLeft;
    };
    std::vector<PreviousPlacement> placements;
    placements.reserve(selectedNodes_.size());
    for (const auto id : selectedNodes_)
        if (const auto* node = findNode(id);
            node != nullptr && !isBoundaryNode(*node)
            && node->collapsed != collapsed)
            placements.push_back({ id, nodeBounds(*node).getPosition() });
    if (placements.empty())
        return;

    for (const auto& placement : placements)
        if (auto* node = findNode(placement.id))
            node->collapsed = collapsed;

    const auto canvas = canvasBounds().toFloat();
    for (const auto& placement : placements) {
        auto* node = findNode(placement.id);
        if (node == nullptr)
            continue;
        const auto current = nodeBounds(*node);
        const auto screenDelta = placement.screenTopLeft - current.getPosition();
        const auto baseWidth = current.getWidth()
                               / std::max(0.001f, viewZoom_);
        const auto baseHeight = current.getHeight()
                                / std::max(0.001f, viewZoom_);
        node->position = graphPosition({
            node->position.x
                + screenDelta.x / std::max(0.001f, viewZoom_)
                    / std::max(1.0f, canvas.getWidth() - baseWidth),
            node->position.y
                + screenDelta.y / std::max(0.001f, viewZoom_)
                    / std::max(1.0f, canvas.getHeight() - baseHeight)
        });
    }
    rebuildEmbeddedSliders();
    refreshSelectionDetails();
    resized();
    repaint(canvasBounds());
    setStatus(tr(collapsed ? "nodes.status.collapsed"
                           : "nodes.status.expanded", "count",
                 juce::String(static_cast<int>(placements.size()))));
    notifyLayoutChanged();
}

void NodeGraphComponent::selectConnectedNodes(const int direction)
{
    if (selectedNodes_.empty())
        return;
    auto connected = selectedNodes_;
    auto frontier = selectedNodes_;
    while (!frontier.empty()) {
        std::set<NodeId> next;
        for (const auto& link : connections_) {
            if (direction <= 0 && frontier.contains(link.destination)
                && !connected.contains(link.source))
                next.insert(link.source);
            if (direction >= 0 && frontier.contains(link.source)
                && !connected.contains(link.destination))
                next.insert(link.destination);
        }
        if (next.empty())
            break;
        connected.insert(next.begin(), next.end());
        frontier = std::move(next);
    }
    selectedNodes_ = std::move(connected);
    selectedCommentId_ = 0;
    selectedConnection_ = -1;
    selectedPortId_ = 0;
    refreshSelectionDetails();
    repaint(canvasBounds());
    setStatus(tr(direction < 0 ? "nodes.flow.upstreamSelected"
                               : direction > 0
                                   ? "nodes.flow.downstreamSelected"
                                   : "nodes.flow.connectedSelected",
                 "count", juce::String(
                     static_cast<int>(selectedNodes_.size()))));
}

void NodeGraphComponent::selectNodesConnectedToPort(
    const NodeId nodeId, const std::uint64_t portId,
    const bool frameSelection)
{
    const auto* node = findNode(nodeId);
    const auto* port = node != nullptr ? findPort(*node, portId) : nullptr;
    if (port == nullptr)
        return;

    std::set<NodeId> connected { nodeId };
    for (const auto& link : connections_) {
        if (port->input && link.destination == nodeId
            && link.destinationPort == portId)
            connected.insert(link.source);
        else if (!port->input && link.source == nodeId
                 && link.sourcePort == portId)
            connected.insert(link.destination);
    }
    if (connected.size() <= 1)
        return;

    selectedNodes_ = std::move(connected);
    selectedCommentId_ = 0;
    selectedConnection_ = -1;
    selectedPortId_ = portId;
    refreshSelectionDetails();
    if (frameSelection)
        frameSelectionOrGraph();
    else
        repaint(canvasBounds());
    setStatus(tr(frameSelection ? "nodes.port.connectedFramed"
                                : "nodes.port.connectedSelected",
                 "count", juce::String(
                     static_cast<int>(selectedNodes_.size()) - 1)));
}

void NodeGraphComponent::resetSelectedGraphInstanceOverrides()
{
    if (editingLocked_ || selectedNodes_.size() != 1)
        return;
    auto* node = findNode(*selectedNodes_.begin());
    const auto* module = node != nullptr ? findModule(node->typeKey) : nullptr;
    if (node == nullptr || module == nullptr)
        return;

    auto changed = false;
    for (auto& parameter : node->interfaceState.parameters) {
        const auto classKey = graphInstanceClassParameterKey(node->id,
                                                              parameter.key);
        const auto classParameter = std::ranges::find_if(
            module->interfaceState.parameters,
            [&classKey](const auto& candidate) {
                return candidate.key == classKey;
            });
        if (classParameter == module->interfaceState.parameters.end()
            || std::abs(parameter.value - classParameter->value) <= 1.0e-9)
            continue;
        parameter.value = juce::jlimit(parameter.minimum, parameter.maximum,
                                       classParameter->value);
        changed = true;
    }
    if (!changed)
        return;

    synchroniseGraphInterface();
    rebuildEmbeddedSliders();
    refreshSelectionDetails();
    queueParameterNotification();
    setStatus(tr("nodes.status.instanceOverridesReset"));
    repaint();
}

void NodeGraphComponent::resetSelectedGraphInstanceInterface()
{
    if (editingLocked_ || selectedNodes_.size() != 1)
        return;
    auto* node = findNode(*selectedNodes_.begin());
    const auto* module = node != nullptr ? findModule(node->typeKey) : nullptr;
    if (node == nullptr || module == nullptr
        || !node->interfaceLayoutOverridden)
        return;

    node->interfaceState = createGraphInstanceInterface(node->id, *module);
    node->interfaceLayoutOverridden = false;
    synchroniseGraphInterface();
    rebuildEmbeddedSliders();
    refreshSelectionDetails();
    notifyLayoutChanged();
    queueParameterNotification();
    setStatus(tr("nodes.status.instanceInterfaceReset"));
    repaint();
}

void NodeGraphComponent::openSelectedSubgraph()
{
    if (selectedNodes_.size() != 1)
        return;
    if (const auto* node = findNode(*selectedNodes_.begin()); node != nullptr)
        openModuleGraphEditor(node->typeKey);
}

void NodeGraphComponent::openGraphManager()
{
    if (graphManagerWindow_ != nullptr) {
        graphManagerWindow_->setVisible(true);
        graphManagerWindow_->toFront(true);
        refreshGraphManager();
        return;
    }

    auto manager = std::make_unique<GraphManagerComponent>();
    graphManager_ = manager.get();
    juce::Component::SafePointer<NodeGraphComponent> safeThis(this);
    manager->setFactoryPresetLoadHandler(
        [safeThis](const juce::String& key) {
            if (safeThis == nullptr)
                return;
            const auto preset = std::find_if(
                safeThis->factoryPresets_.begin(),
                safeThis->factoryPresets_.end(),
                [&key](const auto& value) { return value.key == key; });
            if (preset != safeThis->factoryPresets_.end())
                (void) safeThis->applyFactoryPreset(*preset);
        });
    manager->setUserPresetLoadHandler(
        [safeThis](const juce::File& file) {
            if (safeThis == nullptr)
                return;
            const auto result = safeThis->loadUserGraphPreset(file);
            if (!result)
                safeThis->setStatus(result.getErrorMessage(), true);
        });
    manager->setNodeParameterPresetLoadHandler(
        [safeThis](const juce::File& file) {
            if (safeThis == nullptr)
                return;
            if (safeThis->selectedNodes_.size() != 1) {
                safeThis->setStatus(
                    tr("nodes.error.selectNodeForPreset"), true);
                return;
            }
            const auto result = safeThis->loadNodeParameterPresetForNode(
                *safeThis->selectedNodes_.begin(), file);
            if (result.failed())
                safeThis->setStatus(result.getErrorMessage(), true);
        });
    manager->setRefreshHandler([safeThis] {
        if (safeThis != nullptr)
            safeThis->refreshGraphManager();
    });
    manager->setSubgraphOpenHandler(
        [safeThis](const juce::String& key) {
            if (safeThis != nullptr)
                safeThis->openModuleGraphEditor(key);
        });
    manager->setSubgraphVariantHandler(
        [safeThis](const juce::String& key) {
            if (safeThis != nullptr)
                safeThis->promptCreateGraphVariant(key, false);
        });

    auto window = std::make_unique<ModuleEditorDocumentWindow>(
        tr("graph.manager.title") + " — CyDAW");
    window->setContentOwned(manager.release(), true);
    window->centreWithSize(980, 620);
    window->setVisible(true);
    window->toFront(true);
    graphManagerWindow_ = std::move(window);
    refreshGraphManager();
}

void NodeGraphComponent::showGraphManager()
{
    openGraphManager();
}

void NodeGraphComponent::showGraphMembersPanel()
{
    configurationPanelVisible_ = true;
    configurationPanelShowsPalette_ = false;
    configurationPanelShowsMembers_ = true;
    refreshGraphMembersPanel();
    resized();
    repaint();
    notifyViewChanged();
}

